   813          /* Each array must have two entries: time and record */
   814          root = result.data;
   815          if (root.via.array.size != 2) {
   816              continue;
   817          }
   818
   819          /* Unpack time */
   820          flb_time_pop_from_msgpack(&tms, &result, &obj);
   821
   822          /* Get the record/map */
   823          map = root.via.array.ptr[1];
   824          map_size = map.via.map.size;
   825
   826          if (date_key != NULL) {
   827              msgpack_pack_map(&tmp_pck, map_size + 1);
   828          }
   829          else {
   830              msgpack_pack_map(&tmp_pck, map_size);
   831          }
   832
   833          if (date_key != NULL) {
   834              /* Append date key */
   835              msgpack_pack_str(&tmp_pck, flb_sds_len(date_key));
   836              msgpack_pack_str_body(&tmp_pck, date_key, flb_sds_len(date_key));
   837
   838              /* Append date value */
   839              switch (date_format) {
   840              case FLB_PACK_JSON_DATE_DOUBLE:
   841                  msgpack_pack_double(&tmp_pck, flb_time_to_double(&tms));
   842                  break;
   843              case FLB_PACK_JSON_DATE_ISO8601:
   844              /* Format the time, use microsecond precision not nanoseconds */
   845                  gmtime_r(&tms.tm.tv_sec, &tm);
   846                  s = strftime(time_formatted, sizeof(time_formatted) - 1,
   847                               FLB_PACK_JSON_DATE_ISO8601_FMT, &tm);
