   849                  len = snprintf(time_formatted + s,
   850                                 sizeof(time_formatted) - 1 - s,
   851                                 ".%06" PRIu64 "Z",
   852                                 (uint64_t) tms.tm.tv_nsec / 1000);
   853                  s += len;
   854                  msgpack_pack_str(&tmp_pck, s);
   855                  msgpack_pack_str_body(&tmp_pck, time_formatted, s);
   856                  break;
   857              case FLB_PACK_JSON_DATE_EPOCH:
   858                  msgpack_pack_uint64(&tmp_pck, (long long unsigned)(tms.tm.tv_sec));
